head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05344.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Isu_cd = "", scwin.Isu_nm = "", scwin.Secugrp_id = "", scwin.fr_bz_procs_no = "", scwin.design_dd = "", scwin.Inq_dd = "", scwin.today_dd = "", scwin.fst_dtect_dd = "", scwin.selectedGrdNum = 0;
scwin.trsCnt = 0, scwin.trsTotalCnt = 0, scwin.trsErrCnt = 0;
scwin.trsIdx;
scwin.fn_GetPar, scwin.fn_SetPar;
//
scwin.etp_Invstwarn_design_cd = "04"; //지정연장
scwin.list_bz_tp_cd = "";
scwin.discls_form_cd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_onload = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/etn/EtnMktAct.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchEtnInvstwarn" + "&DIV_IDX=" + DIV_IDX_ETN_INVSTWARN_MST + "&TRS_IDX=" + TRS_IDX_SELECT + "&SECUGRP_ID=" + scwin.Secugrp_id + "&GUBUN_CD=" + scwin.etp_Invstwarn_design_cd + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
    } else {
        var url = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETN_INVSTWARNISU_MST_INOUT";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();

        /* useupdate를 false로 지정함. */
        dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETN_INVSTWARNISU_MST_INOUT";
        dts_Isu.reset();
        dts_Isu.insertRow();
        dts_Isu_Temp.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETN_INVSTWARNISU_MST_INOUT";
        dts_Isu_Temp.reset();
    }
};
scwin.fn_todayDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ETN_INVSTWARN_DATE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstproc.invstwarn_today_dd.select";
    dts_Cand.DataID = encodeURI(url);
    dts_Cand.reset();
    scwin.today_dd = dts_Cand.getCellData(1, "TODAY_DD");
};
scwin.fn_CheckForm = function() {
    if (dts_Isu_Temp.getTotalRow() == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_DesignDd) == "") {
        $c.win.alert("[지정연장일]을 입력하세요.");
        edt_DesignDd.focus();
        return false;
    }
    return true;
};
scwin.fn_copy_dts = function(index) {
    if (dts_Isu.getTotalRow() == 0) {
        dts_Isu.insertRow();
    }
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Isu.setCellData(1, "ISU_CD", dts_Isu_Temp.getCellData(index, "ISU_CD"));
    dts_Isu.setCellData(1, "ISU_NM", dts_Isu_Temp.getCellData(index, "ISU_NM"));
    dts_Isu.setCellData(1, "ISUR_CD", dts_Isu_Temp.getCellData(index, "ISUR_CD"));
    dts_Isu.setCellData(1, "ADD_YN", dts_Isu_Temp.getCellData(index, "ADD_YN"));
    scwin.Isur_cd = dts_Isu_Temp.getCellData(index, "ISUR_CD");
    scwin.Isur_nm = dts_Isu_Temp.getCellData(index, "COM_NM");
};
scwin.fn_save_trs = function() {
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ETP_INVSTWARN_DESIGN_CD", scwin.etp_Invstwarn_design_cd);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISU_CD", dts_Isu.getCellData(1, "ISU_CD"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", dts_Isu.getCellData(1, "ISUR_CD"));
    if (dts_Isu.getCellData(1, "ADD_YN") == "Y") scwin.fn_Instwarn_fstdd();

    else dts_Mst.setCellData(dts_Mst.getRowPosition(), "FST_DESIGN_DD", scwin.fst_dtect_dd);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ADD_YN", dts_Isu.getCellData(1, "ADD_YN"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BAS_DD", scwin.Inq_dd);
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    if (scwin.Secugrp_id == SECUGRP_ID_EN) {
        scwin.list_bz_tp_cd = LIST_BZ_TP_CD_716;
    } else if (scwin.Secugrp_id == SECUGRP_ID_EF) {
        scwin.list_bz_tp_cd = LIST_BZ_TP_CD_750;
    }
    trs.Action = $c.lce.fn_encodeNSession("/etn/EtnMktAct.do?method=saveEtnInvstwarn&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=1" + ",LIST_BZ_TP_CD=" + scwin.list_bz_tp_cd + ",DIV_IDX[0]=" + DIV_IDX_ETN_INVSTWARN_MST;
    trs.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (scwin.fn_duplicate_check() == "Y") {
            return;
        }
        if (!$c.lce.fn_isProcess('I')) return;
        scwin.trsTotalCnt = dts_Isu_Temp.getTotalRow();
        scwin.trsCnt = 0;
        scwin.trsErrCnt = 0;
        for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
            scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
            scwin.fn_copy_dts(i);
            if (scwin.fr_bz_procs_no.length != 14) {
                $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            } else {
                scwin.trsIdx = TRS_IDX_INSERT;
                dts_Isu_Temp.setCellData(i, "STATUS", "N");
                scwin.trsCnt++;
                scwin.fn_save_trs();
            }
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lce.fn_isProcess('U')) return;
        scwin.trsTotalCnt = dts_Isu_Temp.getTotalRow();
        scwin.trsCnt = 0;
        scwin.trsErrCnt = 0;
        for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
            scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(i, "BZ_PROCS_NO");
            scwin.fn_copy_dts(i);
            dts_Isu_Temp.setCellData(i, "STATUS", "N");
            scwin.trsCnt++;
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_delete = function() {
    if (!$c.lce.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus();
    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.trsTotalCnt = dts_Isu_Temp.getTotalRow();
    scwin.trsCnt = 0;
    scwin.trsErrCnt = 0;
    for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
        scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(i, "BZ_PROCS_NO");
        scwin.fn_copy_dts(i);
        dts_Isu_Temp.setCellData(i, "STATUS", "N");
        scwin.trsCnt++;
        scwin.fn_save_trs();
    }
};
scwin.fn_dscl = async function() {
    if (dts_Isu_Temp.getTotalRow() > 1 && scwin.selectedGrdNum == 0) {
        $c.win.alert('종목을 선택해 주세요.');
        return;
    } else if (dts_Isu_Temp.getTotalRow() == 1) {
        scwin.selectedGrdNum = 1;
    }
    scwin.fn_copy_dts(scwin.selectedGrdNum);
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst) {
        if (scwin.Secugrp_id == SECUGRP_ID_EN) {
            scwin.discls_form_cd = "68393"; //상장지수증권 투자유의종목 지정연장 안내공시

        } else if (scwin.Secugrp_id == SECUGRP_ID_EF) {
            scwin.discls_form_cd = "99359"; //ETF 투자유의종목 지정연장

        }
        arr[0] = scwin.discls_form_cd;
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        if (scwin.Secugrp_id == SECUGRP_ID_EN) {
            arr[5] = dts_Isu.getCellData(scwin.selectedGrdNum, "ISU_NM");
        } else if (scwin.Secugrp_id == SECUGRP_ID_EF) {
            arr[5] = "";
        }
        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "COM_NM", dts_Isu_Temp.getCellData(scwin.selectedGrdNum, "COM_NM"));
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 15;
    var hgt = 785 + 40;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_duplicate_check = function() {
    var url = "";
    for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
        var url = "/etn/EtnMktAct.do?method=checkDuplicate&inputMessageId=ETN_INVSTWARNISU_DUK_INOUT";
        url += "&ETP_INVSTWARN_DESIGN_CD=" + scwin.etp_Invstwarn_design_cd;
        url += "&ISU_CD=" + dts_Isu_Temp.getCellData(i, "ISU_CD");
        url += "&BAS_DD=" + scwin.Inq_dd;
        dts_DUP_CHK.DataID = encodeURI(url);
        dts_DUP_CHK.reset();
        if (dts_DUP_CHK.getCellData(1, "DUP_CHK") == "Y") {
            $c.win.alert("중복된 종목이 저장되어 있습니다.");
            return "Y";
        }
    }
    return "N";
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_search;
    fr_fn_list_sync();
};
scwin.fn_SetIsuCdBtnShow = function() {
    if (scwin.fr_bz_procs_no != "" || scwin.Isu_cd != "") {
        img_SetIsuCd.src = "../img/btn_isu_select_d.gif";
        img_SetIsuCd.setDisabled(true);
    } else {
        img_SetIsuCd.src = "../img/btn_isu_select.gif";
        img_SetIsuCd.setDisabled(false);
    }
};
scwin.fn_SelectGridRow = function(row) {
    scwin.selectedGrdNum = row;
    scwin.Isur_cd = dts_Isu_Temp.getCellData(row, "ISUR_CD");
    scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(row, "BZ_PROCS_NO");
};


//종목추가 
scwin.fn_GetParIsu = function(arrPar, param_dts) {
    arrPar[0] = "";
    arrPar[1] = "3"; //상장전체

    $c.stf.CopyDataSet(dts_Isu_Temp, param_dts);
};
scwin.fn_SetParIsu = function(param_dts) {
    $c.stf.CopyDataSet(param_dts, dts_Isu_Temp);
    for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
        dts_Isu_Temp.setCellData(i, "ADD_YN", "Y");
    }
};
scwin.fn_Instwarn_fstdd = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ETN_INVSTWARNISU_MST_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.invstwarnisu.isu_fst_design_dd.select" + "&{P}param01=" + dts_Isu.getCellData(1, "ISU_CD");
    dts_Instwarn.DataID = encodeURI(url);
    dts_Instwarn.reset();
    fst_design_dd = dts_Instwarn.getCellData(1, "FST_DESIGN_DD");
    if (fst_design_dd != "") {
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "FST_DESIGN_DD", fst_design_dd);
    } else {
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "FST_DESIGN_DD", $c.stf.getObjectValue(edt_DesignDd));
    }
};
scwin.trs_OnSuccess = async function() {
    dts_Isu_Temp.setCellData(scwin.trsCnt, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "Y");
    if (scwin.trsCnt == scwin.trsTotalCnt) {
        $c.lce.fn_alertMsg('S');
        scwin.fn_parentRefresh();
        if (dts_Isu_Temp.getTotalRow() == 1) {
            scwin.fn_SelectGridRow(1);
        }
        if (buttonSet.status == "I") {
            buttonSet.setUpdateStatus();
            scwin.fn_SetIsuCdBtnShow();
        } else if (buttonSet.status == "D") {
            await $c.frame.CloseFrame();
        } else {

        }
    }
};
scwin.trs_OnFail = function() {
    $c.stf.alert_error(trs);
    dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "N");
    scwin.trsErrCnt++;
    if (scwin.trsCnt == scwin.trsTotalCnt && scwin.trsErrCnt > 0) {
        $c.lce.fn_alertMsg('F');
        if (buttonSet.status == "D") {
            for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
                if (dts_Isu_Temp.getCellData(i, "STATUS") == "Y") {
                    $c.cp.removeRow(dts_Isu_Temp, i);
                }
            }
        } else {

        }
    }
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
        dts_Mst.insertRow();
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "DESIGN_DD", scwin.design_dd);
        txa_Rsn.Text = "투자유의종목 지정단위기간(3매매거래일) 장종료시 실시간 괴리율이\r\n" + "규정상 관리의무 비율을 1일 이상 초과에 해당";
        txa_InvstwarnContn.Text = "투자유의종목 지정이 연장됨에 따라 지정연장일부터 새로운 투자유의종목 지정단위기간이\r\n" + "시작됩니다. 투자유의종목 지정단위기간 중 장종료시 실시간 괴리율이 규정상 의무범위를 \r\n" + "1일 이상 초과하는 경우 투자유의종목 지정이 재연장될 수 있습니다.\r\n" + "또한, 지정단위기간 종료일의 장종료시 실시간 괴리율이 규정상 의무범위의 3배를 이상인 경우\r\n" + "매매거래가 정지될 수 있습니다.";
        txa_Remk.Text = "-";
    } else {
        $c.stf.CopyDataSet(dts_Mst, dts_Isu_Temp);
        $c.stf.CopyDataSet(dts_Mst, dts_Isu);
        scwin.Isur_cd = dts_Isu_Temp.getCellData(1, "ISUR_CD");
        scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(1, "BZ_PROCS_NO");
        scwin.fn_SetIsuCdBtnShow();
        if (scwin.Inq_dd < scwin.today_dd) {
            buttonSet.setDisableStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    }
};
scwin.dts_Mst_OnLoadError = function() {
    $c.stf.alert_error(dts_Mst);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    dts_Isu.insertRow();
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_Temp_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "" && scwin.Isu_cd != "") {
        dts_Isu_Temp.insertRow();
        dts_Isu_Temp.setCellData(dts_Isu_Temp.getRowPosition(), "ISU_CD", scwin.Isu_cd);
        dts_Isu_Temp.setCellData(dts_Isu_Temp.getRowPosition(), "ISU_NM", scwin.Isu_nm);
        dts_Isu_Temp.setCellData(dts_Isu_Temp.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
    }
};
scwin.dts_Isu_Temp_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu_Temp);
};
scwin.img_SetIsuCd_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsu;
    scwin.fn_SetPar = fn_SetParIsu;
    if (scwin.Secugrp_id == SECUGRP_ID_EN) {
        $c.lce.fn_PopFindEtnCode();
    } else if (scwin.Secugrp_id == SECUGRP_ID_EF) {
        $c.lce.fn_PopFindEtfCode(scwin.Secugrp_id);
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_DesignDd_onclick = function() {
    popUpCalendar2(edt_DesignDd);
};
scwin.grid_1_OnClick = function(row, colid) {
    scwin.fn_SelectGridRow(row);
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar;
    var arrPar = new Array();
    fnc(arrPar);
    scwin.Isu_cd = (arrPar.length >= 1 ? arrPar[0] : "");
    scwin.Isu_nm = (arrPar.length >= 2 ? arrPar[1] : "");
    scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : "");
    Mkt_id = (arrPar.length >= 4 ? arrPar[3] : "");
    scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : "");
    scwin.design_dd = (arrPar.length >= 6 ? arrPar[5] : "");
    scwin.Inq_dd = (arrPar.length >= 7 ? arrPar[6] : "");
    scwin.fst_dtect_dd = (arrPar.length >= 8 ? arrPar[7] : "");
    scwin.Isur_cd = (arrPar.length >= 9 ? arrPar[8] : "");
    buttonSet.setSaveInfo(btn_Save, fn_save);
    buttonSet.setUpdateInfo(btn_Update, fn_update);
    buttonSet.setDeleteInfo(btn_Delete, fn_delete);
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl);
    scwin.fn_SetIsuCdBtnShow();
    scwin.fn_todayDate();
    scwin.fn_onload();
    $c.libRoundPanel.PanelToGroupBox(panel_3);
};
scwin.dts_Cand_OnLoadError = function() {
    $c.stf.alert_error(dts_Cand);
};
scwin.dts_Instwarn_OnLoadError = function() {
    $c.stf.alert_error(dts_Instwarn);
};
